# Generated by the network debugging agent
# Request: measure speed and packet loss from ns1 to ns2 with 1000 UDP packets
# TYPE: two-sided
# Re-run: python tool_builder.py --run tools/udp_speed_loss.py
#!/usr/bin/env python3
"""UDP speed + loss test ns1 -> ns2 with 1000 packets."""
import argparse
import socket
import struct
import sys
import time

DEFAULT_HOST = "10.0.0.2"
DEFAULT_PORT = 5001
DEFAULT_COUNT = 1000
DEFAULT_SIZE = 1024
DEFAULT_PACE = 0.001


def run_sender(host, port, count, pkt_size, pace):
    print(f"[sender] target {host}:{port} count={count} pkt_size={pkt_size} pace={pace}s", flush=True)
    print(f"[sender] RAW config: dest={host}:{port} total={count} bytes_per_pkt={pkt_size}", flush=True)
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(2.0)
    pad_len = max(0, pkt_size - 8)
    pad = b"A" * pad_len
    sent = 0
    send_errors = 0
    wall_start = time.time()
    t_start = time.monotonic()
    try:
        for seq in range(count):
            pkt = struct.pack("!II", seq, count) + pad
            try:
                sock.sendto(pkt, (host, port))
                sent += 1
            except socket.error as e:
                send_errors += 1
                print(f"[sender] send error seq={seq}: {e}", flush=True)
            if seq != count - 1:
                time.sleep(pace)
    finally:
        t_end = time.monotonic()
        wall_end = time.time()
        try:
            sock.close()
        except Exception:
            pass

    duration = t_end - t_start
    total_bytes = sent * pkt_size
    if duration > 0:
        bps = total_bytes * 8 / duration
        pps = sent / duration
    else:
        bps = 0.0
        pps = 0.0
    print("=== SENDER RESULT ===", flush=True)
    print(f"packets_sent: {sent}/{count}", flush=True)
    print(f"send_errors: {send_errors}", flush=True)
    print(f"bytes_sent: {total_bytes}", flush=True)
    print(f"duration_s: {duration:.6f}", flush=True)
    print(f"send_rate_pps: {pps:.2f}", flush=True)
    print(f"throughput_bps: {bps:.2f}", flush=True)
    print(f"throughput_Mbps: {bps/1e6:.4f}", flush=True)
    print(f"throughput_KBps: {(total_bytes/duration if duration>0 else 0):.2f}", flush=True)
    print("=== SENDER RAW EVIDENCE ===", flush=True)
    print(f"RAW wall_start={wall_start:.6f} wall_end={wall_end:.6f} mono_start={t_start:.6f} mono_end={t_end:.6f} duration={duration:.6f} sent={sent} bytes={total_bytes} pkt_size={pkt_size}", flush=True)
    sys.stdout.flush()


def run_receiver(bind_host, port, count_default, idle_timeout=3.0, no_data_timeout=10.0):
    print(f"[receiver] binding {bind_host}:{port}", flush=True)
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(1.0)
    try:
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 1024 * 1024)
    except Exception as e:
        print(f"[receiver] setsockopt note: {e}", flush=True)
    try:
        sock.bind((bind_host, port))
        print(f"[receiver] listening on {bind_host}:{port}", flush=True)
    except OSError as e:
        print(f"[receiver] bind to {bind_host}:{port} failed: {e}", flush=True)
        # fallback to wildcard so test still runs; primary attempt was required address
        try:
            sock.bind(("0.0.0.0", port))
            print(f"[receiver] fallback listening on 0.0.0.0:{port}", flush=True)
        except OSError as e2:
            print(f"[receiver] fallback bind failed: {e2}", flush=True)
            print("=== RECEIVER RESULT ===", flush=True)
            print("packets_received: 0", flush=True)
            print("loss_pct: 100.0", flush=True)
            print("throughput_bps: 0", flush=True)
            print(f"RAW bind_failed primary={e} fallback={e2}", flush=True)
            try:
                sock.close()
            except Exception:
                pass
            return

    start_wait = time.monotonic()
    wall_start = time.time()
    first_recv = None
    last_recv = None
    received_seqs = set()
    bytes_recv = 0
    pkts_incl_dup = 0
    total_expected = None
    first_size = None

    while True:
        now = time.monotonic()
        if first_recv is None:
            if now - start_wait >= no_data_timeout:
                print(f"[receiver] timeout: no packets within {no_data_timeout}s", flush=True)
                break
        else:
            if now - last_recv >= idle_timeout:
                print(f"[receiver] idle timeout: {idle_timeout}s after last packet", flush=True)
                break
        if now - start_wait >= 20.0:
            print("[receiver] overall 20s safety timeout", flush=True)
            break
        try:
            data, addr = sock.recvfrom(65535)
        except socket.timeout:
            continue
        except socket.error as e:
            print(f"[receiver] recv error: {e}", flush=True)
            continue
        recv_now = time.monotonic()
        pkts_incl_dup += 1
        bytes_recv += len(data)
        if first_recv is None:
            first_recv = recv_now
            first_size = len(data)
        last_recv = recv_now
        if len(data) >= 8:
            try:
                seq, total = struct.unpack("!II", data[:8])
                if total_expected is None:
                    # sanity check total
                    if 1 <= total <= 100000:
                        total_expected = total
                    else:
                        total_expected = count_default
                    print(f"[receiver] first packet seq={seq} total={total} size={len(data)} from={addr}", flush=True)
                if 0 <= seq < 1000000:
                    received_seqs.add(seq)
            except struct.error:
                pass
        # optional early progress log
        if pkts_incl_dup == 1 or pkts_incl_dup % 500 == 0:
            print(f"[receiver] progress pkts={pkts_incl_dup} unique={len(received_seqs)} bytes={bytes_recv}", flush=True)

    wall_end = time.time()
    try:
        sock.close()
    except Exception:
        pass

    expected = total_expected if total_expected is not None else count_default
    unique = len(received_seqs)
    lost = max(0, expected - unique)
    loss_pct = (lost / expected * 100.0) if expected > 0 else 100.0
    dup = max(0, pkts_incl_dup - unique)
    if first_recv is not None and last_recv is not None and unique > 1:
        duration = last_recv - first_recv
        if duration < 1e-9:
            duration = 1e-9
        bps = bytes_recv * 8 / duration
        pps = pkts_incl_dup / duration
    else:
        duration = 0.0
        bps = 0.0
        pps = 0.0

    # find missing sample
    missing_sample = []
    if expected is not None and expected <= 5000 and unique < expected:
        for i in range(expected):
            if i not in received_seqs:
                missing_sample.append(i)
                if len(missing_sample) >= 20:
                    break

    print("=== RECEIVER RESULT ===", flush=True)
    print(f"packets_received_unique: {unique}/{expected}", flush=True)
    print(f"packets_received_incl_dup: {pkts_incl_dup}", flush=True)
    print(f"packets_lost: {lost}", flush=True)
    print(f"loss_pct: {loss_pct:.2f}%", flush=True)
    print(f"duplicates: {dup}", flush=True)
    print(f"bytes_received: {bytes_recv}", flush=True)
    print(f"duration_s: {duration:.6f}", flush=True)
    print(f"receive_rate_pps: {pps:.2f}", flush=True)
    print(f"throughput_bps: {bps:.2f}", flush=True)
    print(f"throughput_Mbps: {bps/1e6:.4f}", flush=True)
    print(f"throughput_KBps: {(bytes_recv/duration if duration>0 else 0):.2f}", flush=True)
    print("=== RECEIVER RAW EVIDENCE ===", flush=True)
    print(f"RAW wall_start={wall_start:.6f} wall_end={wall_end:.6f} mono_start_wait={start_wait:.6f} first_recv={first_recv} last_recv={last_recv} duration={duration:.6f} bytes={bytes_recv} pkts_incl_dup={pkts_incl_dup} unique={unique} expected={expected} first_size={first_size}", flush=True)
    if missing_sample:
        print(f"RAW missing_sample_first20={missing_sample} total_missing={lost}", flush=True)
    else:
        print(f"RAW missing_sample=[] total_missing={lost}", flush=True)
    sys.stdout.flush()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--role", required=True, choices=["sender", "receiver"])
    ap.add_argument("--host", default=DEFAULT_HOST)
    ap.add_argument("--port", type=int, default=DEFAULT_PORT)
    ap.add_argument("--count", type=int, default=DEFAULT_COUNT)
    ap.add_argument("--size", type=int, default=DEFAULT_SIZE)
    ap.add_argument("--pace", type=float, default=DEFAULT_PACE)
    args = ap.parse_args()
    try:
        if args.role == "sender":
            run_sender(args.host, args.port, args.count, args.size, args.pace)
        else:
            run_receiver(args.host, args.port, args.count)
    except Exception as e:
        # still exit 0 if test ran but network bad; print error as evidence
        print(f"[{args.role}] ERROR: {e}", flush=True)
        import traceback
        traceback.print_exc()
    sys.exit(0)


if __name__ == "__main__":
    main()
